00012 APC_ArgParser apc_init(int argc, char *argv[])
00013 {
00014     APC_ArgParser parser = {0};
00015 
00016     parser.argc = argc;
00017     parser.argv = argv;
00018     parser.args = cvec_init(-1, sizeof(APC_ArgInfo));
00019     parser.enableColor = true;
00020 
00021     return parser;
00022 }
