00024 APC_ArgInfo apc_initInfo(void)
00025 {
00026     APC_ArgInfo info = {0};
00027     info.aliases = cvec_init(-1, sizeof(const char*));
00028     info.required = false;
00029 
00030     return info;
00031 }
