00033 void apc_destroy(APC_ArgParser *argpar)
00034 {
00035     for (size_t i = 0 ; i < argpar->args.size ; i++)
00036     {
00037         APC_ArgInfo *info = cvec_get(&argpar->args, i);
00038 
00039         if (!info) continue;
00040 
00041         // Destroy
00042         cvec_destroy(&info->aliases);
00043     }
00044 
00045     cvec_destroy(&argpar->args);
00046 }
00047 
00048 bool apc_add(APC_ArgParser *argpar, APC_ArgInfo info)
00049 {
00050     // Make addition checks
00051     if (info.id[0] == '\0' ||
00052             info.param[0] == '\0')
00053         return false;
00054 
00055     // If passed, push it:
00056     cvec_push(&argpar->args, APC_ArgInfo, info);
00057 
00058     return true;
00059 }
00060 
00061 bool apc_get(APC_ArgParser *argpar, const char *id)
00062 {
00063     if (id[0] == '\0'  || !id ||
00064             !argpar)
00065         return false;
00066 
00067     // Check main CVEC ARGS
00068     for (size_t arg = 0 ; arg < argpar->args.size ; arg++)
00069     {
00070         APC_ArgInfo *info = cvec_get(&argpar->args, arg);
00071 
00072         if (!info) continue;
00073 
00074         if (strcmp(info->id, id) != 0)
00075             continue;
00076 
00077         // Check ARGV from apc_init() function
00078         for (int argv = 0 ; argv < argpar->argc ; argv++)
00079         {
00080             if (strcmp(argpar->argv[argv], info->param) == 0 ||
00081                 strcmp(argpar->argv[argv], info->sparam) == 0)
00082                 return true;
00083 
00084             // Parse aliases
00085             for (size_t a = 0 ; a < info->aliases.size ; a++)
00086             {
00087                 char **alias = cvec_get(&info->aliases, a);
00088 
00089                 if (!alias && !*alias)
00090                     continue;
00091 
00092                 if (strcmp(argpar->argv[argv], *alias) == 0)
00093                     return true;
00094             }
00095         }
00096     }
00097 
00098     return false;
00099 }
