00101 char *__apc_setRGB(int r, int g, int b)
00102 {
00103     if (r < 0 || r > 255) return NULL;
00104     if (g < 0 || g > 255) return NULL;
00105     if (b < 0 || b > 255) return NULL;
00106 
00107     CSTR formatted = cstr_init();
00108 
00109     char tmp[16];
00110 
00111     cstr_set(&formatted, "\033[38;2;");
00112 
00113     snprintf(tmp, sizeof(tmp), "%u", r);
00114     cstr_add(&formatted, tmp);
00115     cstr_add(&formatted, ";");
00116 
00117     snprintf(tmp, sizeof(tmp), "%u", g);
00118     cstr_add(&formatted, tmp);
00119     cstr_add(&formatted, ";");
00120 
00121     snprintf(tmp, sizeof(tmp), "%u", b);
00122     cstr_add(&formatted, tmp);
00123     cstr_add(&formatted, "m");
00124 
00125     char *ret = CSTR_sys_strdup(formatted.data);
00126 
00127     cstr_destroy(&formatted);
00128 
00129     return ret;
00130 }
