00132 APC_RGB __apc_rgbToRGBStruct(const char *rgbStr)
00133 {
00134     APC_RGB rgb = {0};
00135     rgb.__externalAction = APC_RGB_Command_None;
00136 
00137     // Reset terminal styles
00138     // Such as color, bolds, italics, etc
00139     if (strcmp(rgbStr, "${R}") == 0)
00140     {
00141         rgb.__externalAction = APC_RGB_Command_Reset;
00142 
00143         rgb.r = 0;
00144         rgb.g = 0;
00145         rgb.b = 0;
00146 
00147         return rgb;
00148     }
00149 
00150     else if (strcmp(rgbStr, "${BOLD}") == 0)
00151     {
00152         rgb.__externalAction = APC_RGB_Command_Bold;
00153 
00154         rgb.r = 0;
00155         rgb.g = 0;
00156         rgb.b = 0;
00157 
00158         return rgb;
00159     }
00160 
00161     else if (strcmp(rgbStr, "${ITALIC}") == 0)
00162     {
00163         rgb.__externalAction = APC_RGB_Command_Italic;
00164 
00165         rgb.r = 0;
00166         rgb.g = 0;
00167         rgb.b = 0;
00168 
00169         return rgb;
00170     }
00171 
00172     else if (strcmp(rgbStr, "${UNDERLINE}") == 0)
00173     {
00174         rgb.__externalAction = APC_RGB_Command_Underline;
00175 
00176         rgb.r = 0;
00177         rgb.g = 0;
00178         rgb.b = 0;
00179 
00180         return rgb;
00181     }
00182 
00183     if (!rgbStr)
00184         return rgb;
00185 
00186     int r, g, b;
00187 
00188     // Get format: ${r,g,b}
00189     if (sscanf(rgbStr, "${%d,%d,%d}", &r, &g, &b) == 3)
00190     {
00191         if (r >= 0 && r <= 255) rgb.r = (unsigned char)r;
00192         if (g >= 0 && g <= 255) rgb.g = (unsigned char)g;
00193         if (b >= 0 && b <= 255) rgb.b = (unsigned char)b;
00194     }
00195 
00196     return rgb;
00197 }
