00199 char *__apc_colorFormat(APC_ArgParser *argpar, const char *msg)
00200 {
00201     CSTR result = cstr_init();
00202     cstr_set(&result, msg);
00203 
00204     if (!argpar->enableColor)
00205     {
00206         // Remove occurrences that have:
00207         // `${` until the next `}`
00208         int pos = 0;
00209 
00210         while (1)
00211         {
00212             const int start = cstr_findFrom(&result, "${", pos);
00213 
00214             if (start == CSTR_NPOS)
00215                 break;
00216 
00217             const int end = cstr_findFrom(&result, "}", start + 2);
00218 
00219             if (end == CSTR_NPOS)
00220                 break;
00221 
00222             int len = (end - start) + 1;
00223 
00224             cstr_erase(&result, start, len);
00225 
00226             pos = start;
00227         }
00228     }
00229 
00230     else
00231     {
00232         // Replace occurrences that have:
00233         // `${` until the next `}`
00234         // With the corresponding color syntax;
00235         // ${r,g,b}
00236 
00237         int pos = 0;
00238 
00239         CSTR substr = cstr_init();
00240 
00241         while (1)
00242         {
00243             const int start = cstr_findFrom(&result, "${", pos);
00244 
00245             if (start == CSTR_NPOS)
00246                 break;
00247 
00248             const int end = cstr_findFrom(&result, "}", start + 2);
00249 
00250             if (end == CSTR_NPOS)
00251                 break;
00252 
00253             int len = (end - start) + 1;
00254 
00255             cstr_set(&substr, result.data);
00256             cstr_substr(&substr, start, len);
00257 
00258             // Set the RGB to the struct and then format it to string to
00259             // output it in an ANSI color format
00260             const APC_RGB rgb = __apc_rgbToRGBStruct(substr.data);
00261 
00262             char *rgbStr = NULL;
00263 
00264             if (rgb.__externalAction == APC_RGB_Command_Reset)
00265                 rgbStr = APC_STYLE_RESET;
00266 
00267             else if (rgb.__externalAction == APC_RGB_Command_Bold)
00268                 rgbStr = APC_STYLE_BOLD;
00269 
00270             else if (rgb.__externalAction == APC_RGB_Command_Italic)
00271                 rgbStr = APC_STYLE_ITALIC;
00272 
00273             else if (rgb.__externalAction == APC_RGB_Command_Underline)
00274                 rgbStr = APC_STYLE_UNDERLINE;
00275 
00276             else rgbStr = __apc_setRGB(rgb.r, rgb.g, rgb.b);
00277 
00278             // 1. Remove `${r,g,b}` with its params
00279             // 2. And Insert ANSI string at same position where it's supposed to be
00280             cstr_erase(&result, start, len);
00281             cstr_insert(&result, rgbStr, start);
00282 
00283             // Move position forward past inserted ANSI sequence
00284             pos = start + strlen(rgbStr);
00285 
00286             // If external action is made
00287             // DO NOT free, or else, it'll crash
00288             if (!rgb.__externalAction) { APC_FREE(rgbStr); }
00289         }
00290 
00291         cstr_destroy(&substr);
00292     }
00293 
00294     char *ret = CSTR_sys_strdup(result.data);
00295 
00296     cstr_destroy(&result);
00297 
00298     return ret;
00299 }
