00301 char *apc_generateHelp(APC_ArgParser *argpar,
00302                        const char *title,
00303                        const char *topInfo,
00304                        const char *lowerInfo)
00305 {
00306     CSTR docs = cstr_init();
00307     cstr_set(&docs, "");
00308 
00309     CSTR tmpContent = cstr_init();
00310     cstr_set(&tmpContent, "");
00311 
00312     char *result = NULL;
00313 
00314     // Title
00315     cstr_clear(&tmpContent);
00316     cstr_add(&tmpContent, APC_STYLECOLOR_TITLE "${BOLD}");
00317     cstr_add(&tmpContent, title ? title : "");
00318     cstr_add(&tmpContent, "${R}\n");
00319 
00320     result = __apc_colorFormat(argpar, tmpContent.data);
00321 
00322     if (result)
00323     {
00324         cstr_add(&docs, result);
00325         APC_FREE(result);
00326     }
00327 
00328     // Top info
00329     cstr_clear(&tmpContent);
00330     cstr_add(&tmpContent, "${ITALIC}");
00331     cstr_add(&tmpContent, topInfo ? topInfo : "");
00332     cstr_add(&tmpContent, "${R}\n");
00333 
00334     result = __apc_colorFormat(argpar, tmpContent.data);
00335 
00336     if (result)
00337     {
00338         cstr_add(&docs, result);
00339         APC_FREE(result);
00340     }
00341 
00342     // MAIN INFO
00343 
00344     for (size_t i = 0 ; i < argpar->args.size ; i++)
00345     {
00346         const APC_ArgInfo *info = cvec_get(&argpar->args, i);
00347 
00348         cstr_clear(&tmpContent);
00349 
00350         // Example:
00351         // help [ --help|-h|-? ]; Show this help
00352         // Structure:
00353         // {ID} [ {param1}|{param2}|{alias1}|{alias2}|{...} ]; {Description}
00354         cstr_add(&tmpContent, info->id);
00355 
00356         // Open optional
00357         if (!info->required)
00358         {
00359             char *parsedColor = __apc_colorFormat(argpar, APC_STYLECOLOR_OPTIONAL);
00360 
00361             cstr_add(&tmpContent, parsedColor);
00362             cstr_add(&tmpContent, " [ ");
00363 
00364             APC_FREE(parsedColor);
00365         }
00366 
00367         cstr_add(&tmpContent, info->param);
00368 
00369         if (strlen(info->sparam) > 0) 
00370         {
00371             cstr_add(&tmpContent, "|");
00372             cstr_add(&tmpContent, info->sparam);
00373         }
00374 
00375         for (size_t i = 0 ; i < info->aliases.size ; i++)
00376         {
00377             const char **aliasName = cvec_get(&info->aliases, i);
00378 
00379             if (!aliasName && !*aliasName)
00380                 continue;
00381 
00382             cstr_add(&tmpContent, "|");
00383             cstr_add(&tmpContent, *aliasName);
00384         }
00385 
00386         // Close optional
00387         if (!info->required)
00388         {
00389             char *parsedColor = __apc_colorFormat(argpar, "${R}");
00390 
00391             cstr_add(&tmpContent, " ]");
00392             cstr_add(&tmpContent, parsedColor);
00393 
00394             APC_FREE(parsedColor);
00395         }
00396 
00397         cstr_add(&tmpContent, "; ");
00398         cstr_add(&tmpContent, info->help);
00399         cstr_add(&tmpContent, "\n");
00400 
00401         cstr_add(&docs, tmpContent.data);
00402     }
00403 
00404     //
00405 
00406     // Lower info
00407     cstr_clear(&tmpContent);
00408     cstr_add(&tmpContent, "${ITALIC}");
00409     cstr_add(&tmpContent, lowerInfo ? lowerInfo : "");
00410     cstr_add(&tmpContent, "${R}");
00411 
00412     result = __apc_colorFormat(argpar, tmpContent.data);
00413 
00414     if (result)
00415     {
00416         cstr_add(&docs, result);
00417         APC_FREE(result);
00418     }
00419 
00420     char *data = CSTR_sys_strdup(docs.data);
00421 
00422     cstr_destroy(&docs);
00423     cstr_destroy(&tmpContent);
00424 
00425     return data;
00426 }
